typeDefinitions.declaration:
export interface HighlightProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  text: string;
  query?: string;
  caseSensitive?: boolean;
  markClassName?: string;
}

example.usage:
import { Highlight, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example() {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <Highlight text="PRJ-2026" query="2026"/>
    </div>
  </>;
}
